const items = $('IG Media').all();
const rows = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  const status = resp.statusCode != null ? Number(resp.statusCode) : null;
  const ok = status != null && status >= 200 && status < 300;
  const body = resp.body || {};
  const data = Array.isArray(body.data) ? body.data : [];
  if (!ok) continue;
  for (let j = 0; j < data.length; j++) {
    const p = data[j];
    if (!p || !p.id) continue;
    rows.push({ json: {
      platform: 'Instagram',
      platform_post_id: String(p.id),
      post_url: p.permalink || '',
      published_at: p.timestamp || '',
      content_type: p.media_type || '',
      caption: p.caption || '',
    }});
  }
}
return rows;

const rows = $input.all().map(i => i.json).filter(p => p && p.platform_post_id);
if (!rows.length) return [{ json: { __no_discovery: true } }];
return rows.map(r => ({ json: r }));

