const items = $('YT Recent Videos').all();
const rows = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  const status = resp.statusCode != null ? Number(resp.statusCode) : null;
  const ok = status != null && status >= 200 && status < 300;
  const body = resp.body || {};
  const data = Array.isArray(body.items) ? body.items : [];
  if (!ok) continue;
  for (let j = 0; j < data.length; j++) {
    const v = data[j];
    const vid = (v.id && v.id.videoId) ? v.id.videoId : null;
    if (!vid) continue;
    const sn = v.snippet || {};
    rows.push({ json: {
      platform: 'YouTube',
      platform_post_id: String(vid),
      post_url: 'https://www.youtube.com/watch?v=' + vid,
      published_at: sn.publishedAt || '',
      content_type: 'video',
      caption: sn.title || '',
    }});
  }
}
return rows;

const input = $('Input').first().json;
// LinkedIn personal/creator has no supported post-discovery API -> emit nothing.
if (String(input.account_type || '').toLowerCase() === 'personal') {
  return [];
}
const items = $('LI Org Posts').all();
const rows = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  const status = resp.statusCode != null ? Number(resp.statusCode) : null;
  const ok = status != null && status >= 200 && status < 300;
  const body = resp.body || {};
  const data = Array.isArray(body.elements) ? body.elements : [];
  if (!ok) continue;
  for (let j = 0; j < data.length; j++) {
    const p = data[j];
    if (!p || !p.id) continue;
    rows.push({ json: {
      platform: 'LinkedIn',
      platform_post_id: String(p.id),
      post_url: '',
      published_at: p.createdAt ? new Date(Number(p.createdAt)).toISOString() : '',
      content_type: 'post',
      caption: p.commentary || '',
    }});
  }
}
return rows;

const input = $('Input').first().json;
return [{ json: {
  run_id: input.run_id || null,
  target_date: input.target_date || null,
  account_id: input.account_id || null,
  platform: input.platform || null,
  data_status: 'FAILED',
  error_message: 'Missing Platform_Account_ID; no post discovery attempted.',
  tracked_posts: 0,
}}];

const input = $('Input').first().json;
const TRACKING_DAYS = 30;
const targetDate = String(input.target_date || '').slice(0, 10);

const discovered = $('Collect Discovered').all()
  .map(i => i.json)
  .filter(p => p && p.platform_post_id);

const masterRows = $('Read Post_Master').all()
  .map(i => i.json)
  .filter(r => r && r.Post_ID);

const existing = {};
for (let i = 0; i < masterRows.length; i++) {
  existing[masterRows[i].Post_ID] = masterRows[i];
}

function makePostId(accId, platform, ppid) {
  return String(accId) + '::' + String(platform) + '::' + String(ppid);
}
function dateOnly(v) {
  if (!v) return null;
  const s = String(v).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : null;
}
function addDays(dateStr, days) {
  const d = new Date(dateStr + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

const out = {};

// 1) Discovered posts -> insert or update identity + refresh Last_Seen.
for (let i = 0; i < discovered.length; i++) {
  const p = discovered[i];
  const postId = makePostId(input.account_id, p.platform, p.platform_post_id);
  const ex = existing[postId];
  const pubDate = dateOnly(p.published_at) || (ex ? dateOnly(ex.Published_At) : null) || targetDate;
  const trackingUntil = addDays(pubDate, TRACKING_DAYS);
  const active = targetDate <= trackingUntil;
  out[postId] = {
    Post_ID: postId,
    Account_ID: input.account_id || '',
    Brand_ID: input.brand_id || '',
    Brand_Name: input.brand_name || '',
    Platform: p.platform || '',
    Platform_Post_ID: p.platform_post_id || '',
    Post_URL: p.post_url || (ex ? ex.Post_URL : '') || '',
    Published_At: p.published_at || (ex ? ex.Published_At : '') || '',
    Content_Type: p.content_type || (ex ? ex.Content_Type : '') || '',
    Caption: p.caption || (ex ? ex.Caption : '') || '',
    First_Seen: (ex && ex.First_Seen) ? ex.First_Seen : targetDate,
    Last_Seen: targetDate,
    Active_Tracking: active ? 'TRUE' : 'FALSE',
    Tracking_Until: trackingUntil,
    Notes: (ex && ex.Notes) ? ex.Notes : '',
    __should_collect: active,
  };
}

// 2) Existing tracked posts for this account not rediscovered this run -> keep window fresh.
for (let i = 0; i < masterRows.length; i++) {
  const r = masterRows[i];
  if (String(r.Account_ID) !== String(input.account_id)) continue;
  if (out[r.Post_ID]) continue;
  const pubDate = dateOnly(r.Published_At) || dateOnly(r.First_Seen) || targetDate;
  const trackingUntil = dateOnly(r.Tracking_Until) || addDays(pubDate, TRACKING_DAYS);
  const active = targetDate <= trackingUntil;
  out[r.Post_ID] = {
    Post_ID: r.Post_ID,
    Account_ID: r.Account_ID || '',
    Brand_ID: r.Brand_ID || '',
    Brand_Name: r.Brand_Name || '',
    Platform: r.Platform || '',
    Platform_Post_ID: r.Platform_Post_ID || '',
    Post_URL: r.Post_URL || '',
    Published_At: r.Published_At || '',
    Content_Type: r.Content_Type || '',
    Caption: r.Caption || '',
    First_Seen: r.First_Seen || targetDate,
    Last_Seen: r.Last_Seen || '',
    Active_Tracking: active ? 'TRUE' : 'FALSE',
    Tracking_Until: trackingUntil,
    Notes: r.Notes || '',
    __should_collect: active,
  };
}

const keys = Object.keys(out);
if (!keys.length) return [];
return keys.map(k => ({ json: out[k] }));

const input = $('Input').first().json;
const rows = $('Compute Tracking').all().map(i => i.json);
const out = [];
for (let i = 0; i < rows.length; i++) {
  const r = rows[i];
  if (!r || !r.__should_collect) continue;
  out.push({ json: {
    run_id: input.run_id || null,
    target_date: input.target_date || null,
    account_id: r.Account_ID || null,
    brand_id: r.Brand_ID || null,
    brand_name: r.Brand_Name || null,
    platform: r.Platform || null,
    account_type: input.account_type || null,
    platform_account_id: input.platform_account_id || null,
    post_id: r.Post_ID || null,
    platform_post_id: r.Platform_Post_ID || null,
    post_url: r.Post_URL || null,
    published_at: r.Published_At || null,
    content_type: r.Content_Type || null,
    caption: r.Caption || null,
  }});
}
return out;
